=:rotating_light: *Lead system error* in "{{ $('On Workflow Error').first().json.workflow.name }}"
Node: {{ $('On Workflow Error').first().json.execution.lastNodeExecuted }}
Error: {{ $('On Workflow Error').first().json.execution.error && $('On Workflow Error').first().json.execution.error.message }}
